"""Record actual review of twenty prospective TRAIN hanging originals."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
NOTES={99900915: 'Dense balcony with many window boxes and hanging/ground plants; complete-instance census hold.', 119847707: 'Arch with numerous hanging containers, some apparently empty/sparse, plus smaller rear pots; target presence and complete census hold.', 87597185: 'Close-up main flowering hanging pot, left partial second pot and dense lower flowers; clipped instance census hold.', 48286181: 'Single black hanging container with purple flowers, clipped pot bottom. Clear manual annotation candidate; straps excluded.', 60784237: 'Main hanging fuchsia plus distant right background flowering container and other possible pots; complete census hold.', 151123894: 'Four prominent garden hanging baskets; exact creator account overlaps historical VAL sources. Do not adopt TRAIN.', 146800790: 'Multiple wall pots, overlapping purple and green foliage plus foreground herb/ground growth; root ownership and census hold.', 169907542: 'One clear black flowering hanging pot in community garden; surrounding trees and ground beds not independent containers. Manual annotation candidate.', 54175048: 'Park entrance with several hanging baskets; creator account overlaps historical VAL sources. Hold.', 73621966: 'Distant small hanging baskets in restaurant window, soil/vegetation visibility and possible additional obscured vessels uncertain. Hold.', 119850663: 'Many roof and window hanging baskets plus ground planting; dense/distant complete census hold.', 200088542: 'Low-angle main hanging basket with long trailing foliage; tiny separate-looking vegetation at far-left edge requires ownership/census review before annotation. Hold.', 84841535: 'Flower close-up with basket obscured, separate right-side vine/flower ownership uncertain; creator link missing. Hold.', 154563608: 'White hanging succulent/flower container against dense ground vegetation; top clipping and long flower-stem ownership need review. Hold.', 169798691: 'Single clearly visible conical woven hanging basket with mixed flowers against brick wall; manual annotation candidate, chain/hook/shadow excluded.', 97592834: 'Nest inside dried hanging planter; living vine ownership from above versus pot unclear. Hold; no fake negative label.', 93210839: 'Low-light hanging flower pot plus partial ground plant; creator account matches historical TEST source. Hold.', 148924383: 'Main planted hanging basket clear, but background wooden planter/raised bed contains additional vegetation with uncertain target scope. Hold.', 3141227: 'Botanical garden with many hanging and ground cactus pots; dense complete census hold.', 159081064: 'Book-fair scene many overhead hanging containers, foreground nursery plants and stage plant displays; dense census hold.'}
CANDIDATES=[48286181,169907542,169798691]
def main():
 source=ROOT/'Datasets/plant-hanging-train-source-v83';manifest=source/'manifest.json';data=json.loads(manifest.read_text());assert len(data['samples'])==20;rows=[]
 for r in data['samples']:
  assert hashlib.sha256((source/r['image']).read_bytes()).hexdigest()==r['sha256']
  rows.append(dict(page_id=r['page_id'],image=r['image'],sha256=r['sha256'],observation=NOTES[r['page_id']],original_actually_viewed=True,annotation_approved=False,reserved_split='train'))
 out=ROOT/'Reports/plant-hanging-train-v83-original-review.json';assert not out.exists();out.write_text(json.dumps(dict(samples=rows,candidate_page_ids=CANDIDATES,held_page_ids=[r['page_id'] for r in rows if r['page_id'] not in CANDIDATES],source_manifest_sha256=hashlib.sha256(manifest.read_bytes()).hexdigest(),training_approved=False,deployment_accepted=False),indent=2),encoding='utf-8');print('All20 actual originals reviewed; three manual annotation candidates, seventeen holds')
if __name__=='__main__':main()
